-- ---------- stored functions ----------
-- create or replace keeps the existing function id and re-points it at the new
-- body, so anything already calling it keeps working.
-- sync_item_batch_quantity()
create or replace function sync_item_batch_quantity()
returns trigger
language plpgsql
as $$
declare
  v_batch_total numeric(12,3);
  v_delta numeric(12,3);
  v_take numeric(12,3);
  v_batch record;
  v_expiry date;
  v_batch_code text;
begin
  if new.item_status <> 'active' then
    return new;
  end if;

  select coalesce(sum(remaining_quantity), 0)
    into v_batch_total
    from inventory_batches
   where item_id = new.id;

  v_delta := new.quantity - v_batch_total;
  if v_delta > 0 then
    v_batch_code := 'CTB-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16));
    insert into inventory_batches
      (batch_code, item_id, received_quantity, remaining_quantity, expiration_date, source_type)
    values
      (v_batch_code, new.id, v_delta, v_delta, new.expiration_date,
       case when tg_op = 'INSERT' then 'opening' else 'adjustment' end);
  elsif v_delta < 0 then
    v_delta := abs(v_delta);
    for v_batch in
      select id, remaining_quantity
        from inventory_batches
       where item_id = new.id and remaining_quantity > 0
       order by received_at desc, id desc
       for update
    loop
      exit when v_delta <= 0;
      v_take := least(v_delta, v_batch.remaining_quantity);
      update inventory_batches
         set remaining_quantity = remaining_quantity - v_take
       where id = v_batch.id;
      v_delta := v_delta - v_take;
    end loop;
  end if;

  if exists (select 1 from inventory_batches where item_id = new.id) then
    select min(expiration_date)
      into v_expiry
      from inventory_batches
     where item_id = new.id and remaining_quantity > 0;

    update items
       set expiration_date = v_expiry
     where id = new.id and expiration_date is distinct from v_expiry;
  end if;

  return new;
end;
$$;

-- sync_single_batch_expiration()
create or replace function sync_single_batch_expiration()
returns trigger
language plpgsql
as $$
declare
  v_open_batches integer;
  v_earliest_expiry date;
begin
  if new.expiration_date is not distinct from old.expiration_date then
    return new;
  end if;

  select count(*), min(expiration_date)
    into v_open_batches, v_earliest_expiry
    from inventory_batches
   where item_id = new.id and remaining_quantity > 0;

  if v_open_batches > 1 and new.expiration_date is distinct from v_earliest_expiry then
    raise exception
      'this item has multiple active batches; edit expiry dates on individual batches';
  elsif v_open_batches = 1 and new.expiration_date is distinct from v_earliest_expiry then
    update inventory_batches
       set expiration_date = new.expiration_date
     where item_id = new.id and remaining_quantity > 0;
  end if;

  return new;
end;
$$;

-- correct_item_batch_counts()
create or replace function correct_item_batch_counts(
  p_item_id uuid,
  p_expected_version integer,
  p_patch jsonb,
  p_batch_adjustments jsonb,
  p_reason text
) returns items
language plpgsql
security definer
as $$
declare
  v_item items;
  v_adjustment record;
  v_batch inventory_batches;
  v_target numeric(12,3);
  v_delta numeric(12,3);
  v_total numeric(12,3);
begin
  if jsonb_typeof(p_batch_adjustments) <> 'array'
     or jsonb_array_length(p_batch_adjustments) = 0 then
    raise exception 'at least one batch quantity correction is required';
  end if;
  if nullif(trim(p_reason), '') is null or length(p_reason) > 500 then
    raise exception 'enter a stock correction reason of 500 characters or fewer';
  end if;
  if jsonb_array_length(p_batch_adjustments) > 500 then
    raise exception 'too many batch corrections in one request';
  end if;
  if (
    select count(*) <> count(distinct value->>'batch_id')
    from jsonb_array_elements(p_batch_adjustments)
  ) then
    raise exception 'a batch can only be corrected once per request';
  end if;

  select * into v_item
    from items
   where id = p_item_id
   for update;
  if not found then
    raise exception 'item not found';
  end if;
  if v_item.version <> p_expected_version then
    raise exception 'item was modified by someone else; refresh and retry';
  end if;

  for v_adjustment in
    select batch_id, quantity
      from jsonb_to_recordset(p_batch_adjustments)
        as entry(batch_id uuid, quantity numeric)
     order by batch_id
  loop
    if v_adjustment.batch_id is null
       or v_adjustment.quantity is null
       or v_adjustment.quantity < 0
       or v_adjustment.quantity > 999999999 then
      raise exception 'each batch needs a valid non-negative quantity';
    end if;

    select * into v_batch
      from inventory_batches
     where id = v_adjustment.batch_id
       and item_id = p_item_id
     for update;
    if not found then
      raise exception 'a selected batch no longer belongs to this item';
    end if;

    v_target := v_adjustment.quantity;
    v_delta := v_target - v_batch.remaining_quantity;
    if v_delta < 0 then
      update inventory_batches
         set remaining_quantity = v_target
       where id = v_batch.id;
    elsif v_delta > 0 then
      insert into inventory_batches
        (batch_code, item_id, received_quantity, remaining_quantity,
         expiration_date, source_type, adjustment_reason)
      values
        ('CTB-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16)),
         p_item_id, v_delta, v_delta, v_batch.expiration_date, 'adjustment',
         trim(p_reason));
    end if;
  end loop;

  if p_patch ? 'expirable'
     and (p_patch->>'expirable')::boolean = false
     and exists (
       select 1 from inventory_batches
        where item_id = p_item_id
          and remaining_quantity > 0
          and expiration_date is not null
     ) then
    raise exception 'remove or resolve dated batches before marking this item non-expiring';
  end if;

  select coalesce(sum(remaining_quantity), 0)
    into v_total
    from inventory_batches
   where item_id = p_item_id;

  update items
     set name = case when p_patch ? 'name' then p_patch->>'name' else name end,
         category_id = case when p_patch ? 'category_id'
           then nullif(p_patch->>'category_id', '')::uuid else category_id end,
         location_id = case when p_patch ? 'location_id'
           then nullif(p_patch->>'location_id', '')::uuid else location_id end,
         supplier_id = case when p_patch ? 'supplier_id'
           then nullif(p_patch->>'supplier_id', '')::uuid else supplier_id end,
         physical_form = case when p_patch ? 'physical_form'
           then p_patch->>'physical_form' else physical_form end,
         unit = case when p_patch ? 'unit' then p_patch->>'unit' else unit end,
         units_per_box = case when p_patch ? 'units_per_box'
           then nullif(p_patch->>'units_per_box', '')::numeric else units_per_box end,
         unit_price = case when p_patch ? 'unit_price'
           then nullif(p_patch->>'unit_price', '')::numeric else unit_price end,
         low_stock_threshold = case when p_patch ? 'low_stock_threshold'
           then (p_patch->>'low_stock_threshold')::numeric else low_stock_threshold end,
         expiration_date = case
           when p_patch ? 'expirable' and (p_patch->>'expirable')::boolean = false
             then null
           when p_patch ? 'expiration_date'
             then nullif(p_patch->>'expiration_date', '')::date
           else expiration_date
         end,
         expirable = case when p_patch ? 'expirable'
           then (p_patch->>'expirable')::boolean else expirable end,
         quantity = v_total,
         version = version + 1,
         updated_at = now()
   where id = p_item_id
  returning * into v_item;

  return v_item;
end;
$$;

-- review_item()
create or replace function review_item(
  p_item_id  uuid,
  p_actor_id uuid,
  p_decision text,     -- 'approve' | 'reject'
  p_note     text default null
) returns items
language plpgsql
security definer
as $$
declare
  v_row items;
begin
  if p_decision not in ('approve','reject') then
    raise exception 'decision must be approve or reject, got %', p_decision;
  end if;

  update items
     set item_status = case when p_decision = 'approve' then 'active' else 'rejected' end,
         reviewed_by = p_actor_id,
         reviewed_at = now(),
         review_note = p_note,
         updated_at = now()
   where id = p_item_id
     -- Only a pending item is awaiting a decision. Re-reviewing an active item
     -- would silently overwrite its reviewer, so it is refused here.
     and item_status = 'pending'
  returning * into v_row;

  if not found then
    raise exception 'item is not awaiting approval';
  end if;

  return v_row;
end;
$$;

-- review_change_request()
create or replace function review_change_request(
  p_request_id uuid,
  p_actor_id   uuid,
  p_decision   text,     -- 'approve' | 'reject'
  p_note       text default null
) returns item_change_requests
language plpgsql
security definer
as $$
declare
  v_req item_change_requests;
  v_item items;
begin
  if p_decision not in ('approve','reject') then
    raise exception 'decision must be approve or reject, got %', p_decision;
  end if;

  update item_change_requests
     set status = case when p_decision = 'approve' then 'approved' else 'rejected' end,
         reviewed_by = p_actor_id,
         reviewed_at = now(),
         review_note = p_note
   where id = p_request_id
     and status = 'pending'
  returning * into v_req;

  if not found then
    raise exception 'change request is not awaiting approval';
  end if;

  if p_decision = 'approve' then
    if v_req.batch_adjustments is not null then
      select * into v_item
        from correct_item_batch_counts(
          v_req.item_id,
          v_req.base_version,
          jsonb_strip_nulls(jsonb_build_object(
            'name', v_req.name,
            'category_id', v_req.category_id,
            'location_id', v_req.location_id,
            'supplier_id', v_req.supplier_id,
            'physical_form', v_req.physical_form,
            'unit', v_req.unit,
            'units_per_box', v_req.units_per_box,
            'unit_price', v_req.unit_price,
            'low_stock_threshold', v_req.low_stock_threshold,
            'expiration_date', v_req.expiration_date,
            'expirable', v_req.expirable
          )),
          v_req.batch_adjustments,
          v_req.correction_reason
        );
    else
    update items
       set name = coalesce(v_req.name, name),
           category_id = coalesce(v_req.category_id, category_id),
           location_id = coalesce(v_req.location_id, location_id),
           supplier_id = coalesce(v_req.supplier_id, supplier_id),
           physical_form = coalesce(v_req.physical_form, physical_form),
           unit = coalesce(v_req.unit, unit),
           units_per_box = coalesce(v_req.units_per_box, units_per_box),
           quantity = coalesce(v_req.quantity, quantity),
           low_stock_threshold = coalesce(v_req.low_stock_threshold, low_stock_threshold),
           expiration_date = case
             when v_req.expirable = false then null
             else coalesce(v_req.expiration_date, expiration_date)
           end,
           expirable = coalesce(v_req.expirable, expirable),
           unit_price = coalesce(v_req.unit_price, unit_price),
           version = version + case when v_req.quantity is not null then 1 else 0 end,
           updated_at = now()
     where id = v_req.item_id
       and version = v_req.base_version
    returning * into v_item;

    if not found then
      raise exception 'item was changed after this request was made — reject it and ask again';
    end if;
    end if;
  end if;

  return v_req;
end;
$$;

-- append_audit()
create or replace function append_audit(
  p_actor_id    uuid,
  p_actor_name  text,
  p_action      text,
  p_entity_type text,
  p_entity_id   text,
  p_details     jsonb,
  -- Optional, and deliberately outside the hash. See the column comments on
  -- audit_log: adding these to the digest would invalidate every row written
  -- under the earlier formula, and a chain that does not verify is worthless.
  -- They have defaults so existing six-argument callers keep working unchanged.
  p_ip_address  text default null,
  p_outcome     text default null
) returns audit_log
language plpgsql
security definer
as $$
declare
  v_prev  text;
  v_row   audit_log;
  v_hash  text;
begin
  -- serialize writers so the chain can't fork
  lock table audit_log in exclusive mode;

  select entry_hash into v_prev from audit_log order by seq desc limit 1;
  v_prev := coalesce(v_prev, 'GENESIS');

  insert into audit_log (actor_id, actor_name, action, entity_type, entity_id, details, prev_hash, entry_hash, ip_address, outcome)
  values (p_actor_id, p_actor_name, p_action, p_entity_type, p_entity_id,
          coalesce(p_details, '{}'::jsonb), v_prev, '', p_ip_address, p_outcome)
  returning * into v_row;

  -- Unchanged from the original formula on purpose. Do not add p_ip_address or
  -- p_outcome here without reading the note above.
  v_hash := encode(digest(
      v_row.seq::text || '|' || v_prev || '|' || p_actor_name || '|' || p_action || '|' ||
      coalesce(p_entity_type,'') || '|' || coalesce(p_entity_id,'') || '|' ||
      coalesce(p_details, '{}'::jsonb)::text,
      'sha256'), 'hex');

  update audit_log set entry_hash = v_hash where seq = v_row.seq returning * into v_row;
  return v_row;
end;
$$;

-- verify_audit_chain()
create or replace function verify_audit_chain()
returns table(broken_seq bigint, reason text)
language plpgsql
as $$
declare
  r          record;
  v_prev     text := 'GENESIS';
  v_expected text;
begin
  for r in select * from audit_log order by seq asc loop
    if r.prev_hash <> v_prev then
      broken_seq := r.seq; reason := 'prev_hash mismatch'; return next; return;
    end if;

    v_expected := encode(digest(
        r.seq::text || '|' || r.prev_hash || '|' || r.actor_name || '|' || r.action || '|' ||
        coalesce(r.entity_type,'') || '|' || coalesce(r.entity_id,'') || '|' ||
        r.details::text,
        'sha256'), 'hex');

    if v_expected <> r.entry_hash then
      broken_seq := r.seq; reason := 'entry_hash mismatch'; return next; return;
    end if;

    v_prev := r.entry_hash;
  end loop;
end;
$$;

-- process_transaction()
create or replace function process_transaction(
  p_type       text,
  p_actor_id   uuid,
  p_actor_name text,
  p_items      jsonb,   -- lines may include a scanned batch_id
  p_note       text default null
) returns jsonb
language plpgsql
security definer
as $$
declare
  v_txn_id  uuid;
  v_req     record;
  v_row     items;
  v_new_qty numeric(12,3);
  v_exp     date;
  v_min_days integer;
  v_loc     text;
  v_batch_id uuid;
  v_batch_code text;
  v_batch record;
  v_remaining numeric(12,3);
  v_take numeric(12,3);
  v_current_exp date;
  v_allocations jsonb;
  v_batch_alloc record;
  v_manual_total numeric(12,3);
  v_seen_batches uuid[];
  v_current_batches jsonb;
  v_results jsonb := '[]'::jsonb;
begin
  if p_type not in ('checkout','restock','waste') then
    raise exception 'invalid transaction type: %', p_type;
  end if;

  if jsonb_array_length(p_items) = 0 then
    raise exception 'no items in transaction';
  end if;

  insert into transactions (type, actor_id, actor_name, note)
  values (p_type, p_actor_id, p_actor_name, p_note)
  returning id into v_txn_id;

  for v_req in
    select (e->>'sku') as sku, (e->>'qty')::numeric as qty,
           nullif(btrim(e->>'exp'), '') as exp_text,
           (e->>'boxes')::numeric as boxes,
           nullif(btrim(e->>'batch_id'), '')::uuid as batch_id,
           nullif(e->'batch_allocations', 'null'::jsonb) as batch_allocations,
           nullif(left(btrim(e->>'note'), 500), '') as item_note,
           nullif(left(btrim(e->>'waste_reason'), 500), '') as waste_reason
    from jsonb_array_elements(p_items) e
  loop
    -- The quantity is checked at the END of this block, not here. A line that
    -- gives `boxes` instead of `qty` arrives with no quantity at all, so a check
    -- up front would reject every box restock as "invalid quantity" before the
    -- conversion had a chance to fill it in.

    -- Postgres rolls an impossible day like 2026-02-30 over into March rather
    -- than rejecting it, so the expiry alerts would then be driven by a date
    -- nobody entered. Cast to date and re-format to catch that, and reject
    -- anything that is not YYYY-MM-DD outright.
    v_exp := null;
    if v_req.exp_text is not null then
      if v_req.exp_text !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception 'invalid expiry date for %', v_req.sku;
      end if;
      begin
        v_exp := v_req.exp_text::date;
      exception when others then
        raise exception 'invalid expiry date for %', v_req.sku;
      end;
      if to_char(v_exp, 'YYYY-MM-DD') <> v_req.exp_text then
        raise exception 'invalid expiry date for %', v_req.sku;
      end if;
    end if;

    select * into v_row from items where sku = v_req.sku for update;
    if not found then
      raise exception 'item not found: %', v_req.sku;
    end if;

    -- A submitted-but-unapproved item is not stock (FR-03). It must not be
    -- moved, restocked or written off before an admin has seen it, or the
    -- approval step becomes decorative.
    if v_row.item_status <> 'active' then
      if v_row.item_status = 'pending' then
        raise exception
          '% is awaiting admin approval and cannot be used yet', v_row.name;
      else
        raise exception '% was rejected by an admin and is not in use', v_row.name;
      end if;
    end if;

    -- Per-box packaging. A restock may be counted in boxes instead of the
    -- item's own unit, which is what a supplier invoice actually says. The
    -- conversion happens here rather than in the UI because the factor lives on
    -- the item, and a client that guessed it would put the wrong number in
    -- stock. Stock is always ultimately stored in the item's own unit.
    if v_req.boxes is not null then
      if p_type <> 'restock' then
        raise exception 'boxes can only be given for a restock of %', v_req.sku;
      end if;
      if v_req.boxes <= 0 then
        raise exception 'invalid box count for %', v_req.sku;
      end if;
      if v_row.units_per_box is null then
        raise exception '% is not stocked by the box', v_row.name;
      end if;
      v_req.qty := v_req.boxes * v_row.units_per_box;
    end if;

    -- Now that any box count has been converted, there must be a real quantity
    -- to move. This is the only place it is checked, so a line that gave neither
    -- a quantity nor a box count is refused here rather than becoming a
    -- zero-value movement.
    if v_req.qty is null or v_req.qty <= 0 then
      raise exception 'invalid quantity for %', v_req.sku;
    end if;

    if p_type <> 'waste' and v_req.waste_reason is not null then
      raise exception 'waste reasons are only valid for waste logs';
    end if;
    if length(
         case
           when v_req.waste_reason is not null
             and position(v_req.waste_reason in coalesce(v_req.item_note, '')) > 0
             then v_req.item_note
           else concat_ws(E'\n', v_req.item_note, v_req.waste_reason)
         end
       ) > 500 then
      raise exception 'item note and waste reason exceed 500 characters for %',
        v_req.sku;
    end if;

    -- Minimum shelf life on receipt. A location can refuse stock that arrives
    -- already too close to its date — the point of a freezer is that things keep
    -- for months, so a delivery with days left is not worth taking. Only a
    -- restock with a date can be judged; a line with no date is not this
    -- function's business, and a checkout or waste log never has new stock.
    if p_type = 'restock' and v_exp is not null then
      select l.min_shelf_life_days, l.name into v_min_days, v_loc
        from locations l where l.id = v_row.location_id;

      if v_min_days is not null
         and v_exp < current_date + (v_min_days || ' days')::interval then
        raise exception
          '% expires on % — % needs at least % more day(s) of shelf life on arrival',
          v_row.name, v_exp, coalesce(v_loc, 'that location'), v_min_days;
      end if;
    end if;

    v_allocations := '[]'::jsonb;
    if p_type = 'restock' then
      if v_req.batch_id is not null or v_req.batch_allocations is not null then
        raise exception 'a restock creates a new batch and cannot target an existing batch';
      end if;
      -- Every receipt is a distinct batch, even when its expiry matches an
      -- earlier delivery. A UUID-derived barcode uniquely identifies the lot.
      v_batch_code := 'CTB-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16));
      insert into inventory_batches
        (batch_code, item_id, received_quantity, remaining_quantity, expiration_date, source_type)
      values
        (v_batch_code, v_row.id, v_req.qty, v_req.qty, v_exp, 'restock')
      returning id into v_batch_id;

      v_allocations := jsonb_build_array(jsonb_build_object(
        'batch_id', v_batch_id,
        'batch_code', v_batch_code,
        'expiration_date', v_exp,
        'quantity', v_req.qty
      ));
      v_new_qty := v_row.quantity + v_req.qty;
    else
      v_remaining := v_req.qty;

      if v_req.batch_allocations is not null then
        if p_type <> 'checkout' then
          raise exception 'manual batch selection is only supported for checkout';
        end if;
        if v_req.batch_id is not null then
          raise exception 'use either a scanned batch or manual batch allocations, not both';
        end if;
        if jsonb_typeof(v_req.batch_allocations) <> 'array'
           or jsonb_array_length(v_req.batch_allocations) = 0 then
          raise exception 'manual batch selection must include at least one batch';
        end if;

        v_manual_total := 0;
        v_seen_batches := '{}'::uuid[];
        for v_batch_alloc in
          select value as allocation
            from jsonb_array_elements(v_req.batch_allocations)
        loop
          v_batch_id := nullif(btrim(v_batch_alloc.allocation->>'batch_id'), '')::uuid;
          v_take := nullif(btrim(v_batch_alloc.allocation->>'qty'), '')::numeric;
          if v_batch_id is null or v_take is null or v_take <= 0 then
            raise exception 'invalid batch allocation for %', v_req.sku;
          end if;
          if v_batch_id = any(v_seen_batches) then
            raise exception 'batch % was selected more than once', v_batch_id;
          end if;
          v_seen_batches := array_append(v_seen_batches, v_batch_id);

          select * into v_batch
            from inventory_batches
           where id = v_batch_id and item_id = v_row.id
           for update;
          if not found then
            raise exception 'the selected batch does not belong to %', v_row.sku;
          end if;
          if v_batch.expiration_date < current_date then
            raise exception 'batch % expired on % and cannot be checked out',
              v_batch.batch_code, v_batch.expiration_date;
          end if;
          if v_batch.remaining_quantity < v_take then
            raise exception 'batch % has only % remaining',
              v_batch.batch_code, v_batch.remaining_quantity;
          end if;

          update inventory_batches
             set remaining_quantity = remaining_quantity - v_take
           where id = v_batch.id;
          v_manual_total := v_manual_total + v_take;
          v_allocations := v_allocations || jsonb_build_array(jsonb_build_object(
            'batch_id', v_batch.id,
            'batch_code', v_batch.batch_code,
            'expiration_date', v_batch.expiration_date,
            'quantity', v_take
          ));
        end loop;

        if v_manual_total <> v_req.qty then
          raise exception 'selected batch quantities total %, but checkout quantity is %',
            v_manual_total, v_req.qty;
        end if;
      elsif v_req.batch_id is not null then
        select * into v_batch
          from inventory_batches
         where id = v_req.batch_id and item_id = v_row.id
         for update;
        if not found then
          raise exception 'the scanned batch does not belong to %', v_row.sku;
        end if;
        if p_type = 'checkout' and v_batch.expiration_date < current_date then
          raise exception 'batch % expired on % and cannot be checked out',
            v_batch.batch_code, v_batch.expiration_date;
        end if;
        if p_type = 'waste'
           and (v_batch.expiration_date is null or v_batch.expiration_date >= current_date)
           and v_req.waste_reason is null then
          raise exception 'a reason is required to waste non-expired batch %',
            v_batch.batch_code;
        end if;
        if v_batch.remaining_quantity < v_remaining then
          raise exception 'batch % has only % remaining',
            v_batch.batch_code, v_batch.remaining_quantity;
        end if;

        update inventory_batches
           set remaining_quantity = remaining_quantity - v_remaining
         where id = v_batch.id;
        v_allocations := jsonb_build_array(jsonb_build_object(
          'batch_id', v_batch.id,
          'batch_code', v_batch.batch_code,
          'expiration_date', v_batch.expiration_date,
          'quantity', v_remaining
        ));
      else
        -- Checkout uses FEFO and never takes expired stock. Waste consumes the
        -- oldest lot first so expired stock is written off before good stock.
        for v_batch in
          select *
            from inventory_batches
           where item_id = v_row.id
             and remaining_quantity > 0
             and (
               (p_type = 'waste' and expiration_date < current_date)
               or (
                 p_type = 'checkout'
                 and (expiration_date is null or expiration_date >= current_date)
               )
             )
           order by expiration_date asc nulls last, received_at asc, id asc
           for update
        loop
          exit when v_remaining <= 0;
          v_take := least(v_remaining, v_batch.remaining_quantity);
          update inventory_batches
             set remaining_quantity = remaining_quantity - v_take
           where id = v_batch.id;
          v_allocations := v_allocations || jsonb_build_array(jsonb_build_object(
            'batch_id', v_batch.id,
            'batch_code', v_batch.batch_code,
            'expiration_date', v_batch.expiration_date,
            'quantity', v_take
          ));
          v_remaining := v_remaining - v_take;
        end loop;

        if v_remaining > 0 then
          if p_type = 'checkout' then
            raise exception 'insufficient non-expired stock for % (need % more)',
              v_row.sku, v_remaining;
          elsif p_type = 'waste' then
            raise exception 'insufficient expired stock for automatic waste of % (need % more); select a batch and provide a reason to waste non-expired stock',
              v_row.sku, v_remaining;
          else
            raise exception 'insufficient stock for % (need % more)',
              v_row.sku, v_remaining;
          end if;
        end if;
      end if;

      select coalesce(sum(remaining_quantity), 0)
        into v_new_qty
        from inventory_batches
       where item_id = v_row.id;
    end if;

    -- Keep the compatibility total and single-date field aligned with the
    -- remaining batches. Expiry is the earliest date among lots still on hand.
      select min(expiration_date)
        into v_current_exp
        from inventory_batches
       where item_id = v_row.id and remaining_quantity > 0;

      update items
         set quantity = v_new_qty,
             version = version + 1,
             updated_at = now(),
             expiration_date = v_current_exp
     where id = v_row.id and version = v_row.version;

    if not found then
      raise exception 'concurrent modification on % — please retry', v_row.sku;
    end if;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', id,
          'batch_code', batch_code,
          'received_quantity', received_quantity,
          'remaining_quantity', remaining_quantity,
          'expiration_date', expiration_date,
          'received_at', received_at
        )
        order by expiration_date asc nulls last, received_at asc, id asc
      ),
      '[]'::jsonb
    )
      into v_current_batches
      from inventory_batches
     where item_id = v_row.id and remaining_quantity > 0;

    insert into transaction_items
      (transaction_id, item_id, sku, item_name, quantity, qty_before, qty_after,
       expiration_date, note, batch_allocations)
    values
      (v_txn_id, v_row.id, v_row.sku, v_row.name, v_req.qty, v_row.quantity, v_new_qty,
       case
         when p_type = 'restock' then v_exp
         when p_type = 'checkout' and jsonb_array_length(v_allocations) = 1
           then nullif(v_allocations->0->>'expiration_date', '')::date
         when p_type = 'checkout' then null
         else v_row.expiration_date
       end,
       nullif(
         case
           when v_req.waste_reason is not null
             and position(v_req.waste_reason in coalesce(v_req.item_note, '')) > 0
             then v_req.item_note
           else concat_ws(E'\n', v_req.item_note, v_req.waste_reason)
         end,
         ''
       ),
       v_allocations);

    v_results := v_results || jsonb_build_object(
      'sku', v_row.sku,
      'name', v_row.name,
      'unit', v_row.unit,
      'before', v_row.quantity,
      'after', v_new_qty,
      -- What was actually added, in the item's own unit. When the line was
      -- given in boxes this is the converted figure, so the caller can show
      -- "3 boxes = 36 pcs" rather than silently restocking the wrong amount.
      'added', v_new_qty - v_row.quantity,
      'boxes', case when v_req.boxes is not null then v_req.boxes end,
      'units_per_box', v_row.units_per_box,
      'expiration', to_char(v_current_exp, 'YYYY-MM-DD'),
      'batches', v_allocations,
      'current_batches', v_current_batches
    );
  end loop;

  return jsonb_build_object(
    'transaction_id', v_txn_id,
    'type', p_type,
    'items', v_results
  );
end;
$$;

-- enqueue_email_alerts()
create or replace function enqueue_email_alerts()
returns integer
language plpgsql
security definer
as $$
declare
  v_window_hours integer;
  v_queued       integer := 0;
  v_total        integer := 0;
  v_body         text;
  v_alert        record;
begin
  -- Suppression window (NFR-07: no duplicate for the same item within 24h).
  select coalesce(value::int, 24) into v_window_hours
    from settings where key = 'email_dedupe_hours';
  v_window_hours := coalesce(v_window_hours, 24);

  -- No recipients, no work. Checked first so the common case is one index probe.
  if not exists (select 1 from email_recipients where is_active) then
    return 0;
  end if;

  for v_alert in
    select a.id, a.type, a.message, a.created_at,
           s.name         as supplier_name,
           s.contact_name as supplier_contact,
           s.phone        as supplier_phone,
           s.email        as supplier_email
      from alerts a
      -- The alert names the item; the item names the supplier it was last
      -- received from. Joining here is what keeps the email as actionable as
      -- the in-app alert, which has shown the supplier since suppliers were
      -- introduced. A left join because an item need not have a supplier.
      left join items i on i.id = a.item_id
      left join suppliers s on s.id = i.supplier_id
     where a.resolved = false
       -- Only alerts raised from here on. Without this a backfill would mail
       -- the owner about every open alert the day the feature was switched on.
       and a.created_at > now() - make_interval(hours => v_window_hours)
  loop
    v_body := v_alert.message || ' (' || v_alert.type || ')';

    /*
     * A low-stock email that names only the item still leaves the owner to
     * work out who to ring. The in-app alert has carried the supplier for as
     * long as suppliers have existed; the email is the copy that reaches the
     * owner away from the counter, so it is the one that most needs the number.
     * Expiry alerts are left alone: they are about a date, not a reorder.
     */
    if v_alert.type in ('low_stock', 'out_of_stock')
       and v_alert.supplier_name is not null then
      v_body := v_body || E'\n\nSupplier: ' || v_alert.supplier_name;
      if v_alert.supplier_contact is not null and v_alert.supplier_contact <> '' then
        v_body := v_body || E'\n  contact: ' || v_alert.supplier_contact;
      end if;
      if v_alert.supplier_phone is not null and v_alert.supplier_phone <> '' then
        v_body := v_body || E'\n  phone:   ' || v_alert.supplier_phone;
      end if;
      if v_alert.supplier_email is not null and v_alert.supplier_email <> '' then
        v_body := v_body || E'\n  email:   ' || v_alert.supplier_email;
      end if;
    end if;

    insert into email_notifications
      (alert_id, recipient_id, kind, subject, body, dedupe_key)
    select v_alert.id,
           r.id,
           v_alert.type,
           'CafeTrack: ' || initcap(replace(v_alert.type, '_', ' ')),
           v_body,
           'alert:' || v_alert.id::text || ':' || v_alert.type
      from email_recipients r
     where r.is_active
       -- Empty subscriptions means "send everything" — see the column comment.
       and (cardinality(r.subscriptions) = 0
            or v_alert.type = any (r.subscriptions))
       -- The suppression window, per recipient. Deliberately covers `queued` and
       -- `sending`, not just `sent`: refresh_alerts() runs after every
       -- movement, so an alert raised by a checkout and then by the restock a
       -- minute later would otherwise queue twice before either is sent. A
       -- `failed` row does not suppress — that one is meant to be retried.
       and not exists (
         select 1 from email_notifications e
          where e.dedupe_key = 'alert:' || v_alert.id::text || ':' || v_alert.type
            and e.recipient_id = r.id
            and e.status in ('queued','sending','sent')
            and e.queued_at > now() - make_interval(hours => v_window_hours)
       )
     on conflict do nothing;

    -- ROW_COUNT is per statement inside a loop, so it has to be accumulated
    -- rather than assigned — the loop body's last statement is the insert.
    GET DIAGNOSTICS v_queued = ROW_COUNT;
    v_total := v_total + v_queued;
  end loop;

  return v_total;
end;
$$;

-- enqueue_daily_summary()
create or replace function enqueue_daily_summary()
returns integer
language plpgsql
security definer
as $$
declare
  v_body   text;
  v_count  integer := 0;
begin
  if not exists (select 1 from email_recipients where is_active) then
    return 0;
  end if;

  select
      'Movements: ' || count(*)
   || E'\n  checked out: ' || count(*) filter (where type = 'checkout')
   || E'\n  restocked:   ' || count(*) filter (where type = 'restock')
   || E'\n  waste:       ' || count(*) filter (where type = 'waste')
  into v_body
    from transactions
   where created_at >= date_trunc('day', now());

  v_body := v_body || E'\n\nStill open: '
    || (select count(*) from alerts where resolved = false)
    || E'\n  low/out of stock: '
    || (select count(*) from alerts where resolved = false and type in ('low_stock','out_of_stock'))
    || E'\n  expiring/expired: '
    || (select count(*) from alerts where resolved = false and type in ('near_expiry','expired'))
    || E'\n\nFailed sign-in attempts today: '
    || (select count(*) from login_attempts where success = false and created_at >= date_trunc('day', now()));

  insert into email_notifications
    (recipient_id, kind, subject, body, dedupe_key)
  select r.id,
         'daily_summary',
         'CafeTrack daily summary — ' || to_char(current_date, 'DD Mon YYYY'),
         v_body,
         'daily_summary:' || current_date::text
    from email_recipients r
   where r.is_active
     and (cardinality(r.subscriptions) = 0 or 'daily_summary' = any (r.subscriptions))
     and not exists (
       select 1 from email_notifications e
        where e.dedupe_key = 'daily_summary:' || current_date::text
          and e.recipient_id = r.id
          and e.status in ('queued','sending','sent')
     )
  on conflict do nothing;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  return v_count;
end;
$$;

-- enqueue_failed_login_alert()
create or replace function enqueue_failed_login_alert(p_username text, p_method text, p_reason text)
returns integer
language plpgsql
security definer
as $$
declare
  v_count integer := 0;
  v_body  text;
begin
  if not exists (select 1 from email_recipients where is_active) then
    return 0;
  end if;

  -- Deliberately does not name the credential: an unknown code is logged as a
  -- hash prefix, and putting the raw value in an email would undo that.
  v_body := 'A sign-in attempt was rejected.'
    || E'\n  method: ' || p_method
    || E'\n  reason: ' || p_reason
    || E'\n  when:   ' || to_char(now(), 'DD Mon YYYY HH24:MI')
    || E'\n\nIf this was not you, change the password for that account.';

  insert into email_notifications
    (recipient_id, kind, subject, body, dedupe_key)
  select r.id,
         'failed_login',
         'CafeTrack: rejected sign-in attempt',
         v_body,
         'failed_login:' || p_method || ':' || to_char(date_trunc('hour', now()), 'YYYYMMDDHH24')
    from email_recipients r
   where r.is_active
     and (cardinality(r.subscriptions) = 0 or 'failed_login' = any (r.subscriptions))
     and not exists (
       select 1 from email_notifications e
        where e.dedupe_key = 'failed_login:' || p_method || ':'
              || to_char(date_trunc('hour', now()), 'YYYYMMDDHH24')
          and e.recipient_id = r.id
          and e.status in ('queued','sending','sent')
     )
  on conflict do nothing;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  return v_count;
end;
$$;

-- refresh_alerts()
create or replace function refresh_alerts()
returns void
language plpgsql
security definer
as $$
declare
  v_days int;
begin
  select coalesce(value::int, 7) into v_days from settings where key = 'expiry_warning_days';
  v_days := coalesce(v_days, 7);

  -- Escalate an open stock alert in place, before opening new ones.
  --
  -- The insert below only fires for an item with no open stock alert, so an
  -- item that drops below its threshold and then reaches zero used to keep
  -- saying "is low on stock (1 pcs left)" about an item sitting at zero. This
  -- rewrites the type and the message to match the item's current severity.
  -- The alert keeps its identity (same id, no new row), so nothing duplicates
  -- and the operator's history of it stays intact.
  update alerts a
     set type = case when i.quantity <= 0 then 'out_of_stock' else 'low_stock' end,
         message = case when i.quantity <= 0
                        then i.name || ' is out of stock'
                        else i.name || ' is low on stock (' || i.quantity || ' ' || i.unit || ' left)'
                   end,
         updated_at = now()
    from items i
   where i.id = a.item_id
     and a.resolved = false
     and a.type in ('low_stock','out_of_stock')
     and (
       a.type is distinct from
         (case when i.quantity <= 0 then 'out_of_stock' else 'low_stock' end)
       or a.message is distinct from
         (case when i.quantity <= 0
           then i.name || ' is out of stock'
           else i.name || ' is low on stock (' || i.quantity || ' ' || i.unit || ' left)'
         end)
     );

  -- Expiry alerts describe the affected lots, not the item's aggregate
  -- earliest date. One item can have both expired and usable batches.
  update alerts a
     set type = case when lot_status.expired_quantity > 0 then 'expired' else 'near_expiry' end,
         message = i.name ||
           case when lot_status.expired_quantity > 0 then
             ' has expired batch stock: ' || lot_status.expired_details ||
             case when lot_status.usable_quantity > 0
               then '; ' || lot_status.usable_quantity || ' ' || i.unit || ' remains usable'
               else ''
             end
           else
             ' has batch stock expiring soon: ' || lot_status.soon_details
           end,
         updated_at = now()
    from items i
    cross join lateral (
      select
        coalesce(sum(b.remaining_quantity) filter (where b.expiration_date < current_date), 0) as expired_quantity,
        coalesce(sum(b.remaining_quantity) filter (where b.expiration_date between current_date and current_date + (v_days || ' days')::interval), 0) as soon_quantity,
        coalesce(sum(b.remaining_quantity) filter (where b.expiration_date is null or b.expiration_date >= current_date), 0) as usable_quantity,
        string_agg(
          b.batch_code || ': ' || b.remaining_quantity || ' ' || i.unit || ' (expired ' || b.expiration_date || ')',
          ', '
        ) filter (where b.expiration_date < current_date) as expired_details,
        string_agg(
          b.batch_code || ': ' || b.remaining_quantity || ' ' || i.unit || ' (expires ' || b.expiration_date || ')',
          ', '
        ) filter (where b.expiration_date between current_date and current_date + (v_days || ' days')::interval) as soon_details
      from inventory_batches b
      where b.item_id = i.id and b.remaining_quantity > 0
    ) lot_status
   where i.id = a.item_id
     and i.item_status = 'active'
     and i.expirable = true
     and a.resolved = false
     and a.type in ('near_expiry','expired')
     and (lot_status.expired_quantity > 0 or lot_status.soon_quantity > 0)
     and (
       a.type is distinct from
         (case when lot_status.expired_quantity > 0 then 'expired' else 'near_expiry' end)
       or a.message is distinct from
         (i.name ||
           case when lot_status.expired_quantity > 0 then
             ' has expired batch stock: ' || lot_status.expired_details ||
             case when lot_status.usable_quantity > 0
               then '; ' || lot_status.usable_quantity || ' ' || i.unit || ' remains usable'
               else ''
             end
           else
             ' has batch stock expiring soon: ' || lot_status.soon_details
           end)
     );

  -- open stock alerts
  insert into alerts (item_id, type, message)
  select i.id,
         case when i.quantity <= 0 then 'out_of_stock' else 'low_stock' end,
         case when i.quantity <= 0
              then i.name || ' is out of stock'
              else i.name || ' is low on stock (' || i.quantity || ' ' || i.unit || ' left)'
         end
  from items i
  -- item_status: a submitted or rejected ingredient is not stock yet, so it
  -- must not raise a low-stock or expiry alert. Without this a staff submission
  -- arriving at quantity 0 would email the owner about an item that does not
  -- officially exist.
  where i.item_status = 'active'
    and i.quantity <= i.low_stock_threshold
    and not exists (
      select 1 from alerts a
      where a.item_id = i.id and a.resolved = false
        and a.type in ('low_stock','out_of_stock')
    );

  -- One expiry alert per item, naming the affected batches and quantities.
  insert into alerts (item_id, type, message)
  select i.id,
         case when lot_status.expired_quantity > 0 then 'expired' else 'near_expiry' end,
         i.name ||
           case when lot_status.expired_quantity > 0 then
             ' has expired batch stock: ' || lot_status.expired_details ||
             case when lot_status.usable_quantity > 0
               then '; ' || lot_status.usable_quantity || ' ' || i.unit || ' remains usable'
               else ''
             end
           else
             ' has batch stock expiring soon: ' || lot_status.soon_details
           end
    from items i
    cross join lateral (
      select
        coalesce(sum(b.remaining_quantity) filter (where b.expiration_date < current_date), 0) as expired_quantity,
        coalesce(sum(b.remaining_quantity) filter (where b.expiration_date between current_date and current_date + (v_days || ' days')::interval), 0) as soon_quantity,
        coalesce(sum(b.remaining_quantity) filter (where b.expiration_date is null or b.expiration_date >= current_date), 0) as usable_quantity,
        string_agg(
          b.batch_code || ': ' || b.remaining_quantity || ' ' || i.unit || ' (expired ' || b.expiration_date || ')',
          ', '
        ) filter (where b.expiration_date < current_date) as expired_details,
        string_agg(
          b.batch_code || ': ' || b.remaining_quantity || ' ' || i.unit || ' (expires ' || b.expiration_date || ')',
          ', '
        ) filter (where b.expiration_date between current_date and current_date + (v_days || ' days')::interval) as soon_details
      from inventory_batches b
      where b.item_id = i.id and b.remaining_quantity > 0
    ) lot_status
  where i.item_status = 'active'
    and i.expirable = true
    and (lot_status.expired_quantity > 0 or lot_status.soon_quantity > 0)
    and not exists (
      select 1 from alerts a
      where a.item_id = i.id and a.resolved = false
        and a.type in ('near_expiry','expired')
    );

  -- Email (FR-11). Queue one message per newly-opened alert, per recipient who
  -- subscribed to that family. Wrapped so a cafe with no recipients, or with
  -- email switched off, still gets its alerts: enqueue_email_alerts is called
  -- on every refresh_alerts, so it must never be able to fail the refresh.
  begin
    perform enqueue_email_alerts();
  exception when others then
    -- Swallowed on purpose. An alert that was raised must not be lost because
    -- the mail side had a problem; the queue is a convenience, not the record.
    null;
  end;

  -- auto-resolve stock alerts that cleared
  update alerts a
     set resolved = true,
         resolved_by = coalesce((
           select t.actor_name
             from transactions t
             join transaction_items ti on ti.transaction_id = t.id
            where t.type = 'restock'
              and ti.item_id = i.id
              and t.created_at >= a.created_at
            order by t.created_at desc, t.id desc
            limit 1
         ), 'system'),
         resolved_at = coalesce((
           select t.created_at
             from transactions t
             join transaction_items ti on ti.transaction_id = t.id
            where t.type = 'restock'
              and ti.item_id = i.id
              and t.created_at >= a.created_at
            order by t.created_at desc, t.id desc
            limit 1
         ), now()),
         resolved_reason = coalesce((
           select 'Stock replenished by ' || t.actor_name || ' via restock (' ||
                  ti.quantity || ' ' || i.unit || ').' ||
                  case
                    when nullif(btrim(concat_ws(' — ', t.note, ti.note)), '') is null then ''
                    else ' Note: ' || concat_ws(' — ', t.note, ti.note)
                  end
             from transactions t
             join transaction_items ti on ti.transaction_id = t.id
            where t.type = 'restock'
              and ti.item_id = i.id
              and t.created_at >= a.created_at
            order by t.created_at desc, t.id desc
            limit 1
         ), 'Stock level recovered above the configured low-stock threshold.'),
         updated_at = now()
    from items i
   where a.resolved = false
     and a.type in ('low_stock','out_of_stock')
     and i.id = a.item_id
     and i.quantity > i.low_stock_threshold;

  -- Resolve each expiry severity only after its affected batches are gone or
  -- no longer inside the warning window.
  update alerts a
     set resolved = true,
         resolved_by = coalesce((
           select t.actor_name
             from transactions t
             join transaction_items ti on ti.transaction_id = t.id
            where t.type in ('waste','checkout')
              and ti.item_id = i.id
              and t.created_at >= a.created_at
              and exists (
                select 1
                  from jsonb_array_elements(ti.batch_allocations) allocation
                 where nullif(allocation->>'expiration_date', '')::date is not null
                   and (allocation->>'expiration_date')::date <
                       case when a.type = 'expired'
                         then current_date
                         else current_date + (v_days || ' days')::interval
                       end
                   and (
                     allocation->>'batch_code' is null
                     or position(allocation->>'batch_code' in a.message) > 0
                   )
              )
            order by t.created_at desc, t.id desc
            limit 1
         ), 'system'),
         resolved_at = coalesce((
           select t.created_at
             from transactions t
             join transaction_items ti on ti.transaction_id = t.id
            where t.type in ('waste','checkout')
              and ti.item_id = i.id
              and t.created_at >= a.created_at
              and exists (
                select 1
                  from jsonb_array_elements(ti.batch_allocations) allocation
                 where nullif(allocation->>'expiration_date', '')::date is not null
                   and (allocation->>'expiration_date')::date <
                       case when a.type = 'expired'
                         then current_date
                         else current_date + (v_days || ' days')::interval
                       end
                   and (
                     allocation->>'batch_code' is null
                     or position(allocation->>'batch_code' in a.message) > 0
                   )
              )
            order by t.created_at desc, t.id desc
            limit 1
         ), now()),
         resolved_reason = coalesce((
           select case
                    when t.type = 'waste' then
                      'Expired/near-expiry stock logged as waste by ' || t.actor_name ||
                      ' (' || ti.quantity || ' ' || i.unit || ').'
                    else
                      'Expiring batch used in checkout by ' || t.actor_name ||
                      ' (' || ti.quantity || ' ' || i.unit || ').'
                  end ||
                  case
                    when nullif(btrim(concat_ws(' — ', t.note, ti.note)), '') is null then ''
                    else ' Note: ' || concat_ws(' — ', t.note, ti.note)
                  end
             from transactions t
             join transaction_items ti on ti.transaction_id = t.id
            where t.type in ('waste','checkout')
              and ti.item_id = i.id
              and t.created_at >= a.created_at
              and exists (
                select 1
                  from jsonb_array_elements(ti.batch_allocations) allocation
                 where nullif(allocation->>'expiration_date', '')::date is not null
                   and (allocation->>'expiration_date')::date <
                       case when a.type = 'expired'
                         then current_date
                         else current_date + (v_days || ' days')::interval
                       end
                   and (
                     allocation->>'batch_code' is null
                     or position(allocation->>'batch_code' in a.message) > 0
                   )
              )
            order by t.created_at desc, t.id desc
            limit 1
         ), 'The affected expired or near-expiry batches are no longer in stock.'),
         updated_at = now()
    from items i
   where a.resolved = false
     and a.type in ('near_expiry','expired')
     and i.id = a.item_id
     and (
           i.expirable = false
           or not exists (
             select 1
               from inventory_batches b
              where b.item_id = i.id
                and b.remaining_quantity > 0
                and case when a.type = 'expired'
                  then b.expiration_date < current_date
                  else b.expiration_date between current_date and current_date + (v_days || ' days')::interval
                end
           )
         );
end;
$$;

-- ---------- batch inventory triggers ----------
drop trigger if exists items_sync_batch_quantity on items;
create trigger items_sync_batch_quantity
after insert or update of quantity, item_status on items
for each row execute function sync_item_batch_quantity();

drop trigger if exists items_sync_single_batch_expiration on items;
create trigger items_sync_single_batch_expiration
before update of expiration_date on items
for each row execute function sync_single_batch_expiration();

-- ---------- after applying ----------
-- Force the current state to be recomputed so the new logic takes effect on
-- anything that is already flagged:
--
--   select refresh_alerts();
